// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(uint256 privKey, uint256 duration, uint256 strike, uint256 premium, uint256 nonce) public {
        privKey = bound(privKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        duration = bound(duration, 1, 9999 days);
        strike = bound(strike, 1, type(uint128).max);
        premium = bound(premium, 0, type(uint128).max);
        nonce = bound(nonce, 0, type(uint64).max);

        address maker = vm.addr(privKey);
        address taker = address(0xBEEF);
        // Use this test contract as baseAsset so it has code and supports the ERC20 surface used by fillOrder.
        address baseAsset = address(this);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: maker,
            isCall: false,
            isLong: false,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + 1 days,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new PuttyV2.ERC20Asset[](0),
            erc721Assets: new PuttyV2.ERC721Asset[](0)
        });

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(privKey, orderHash);
        bytes memory signature = abi.encodePacked(r, s, v);

        vm.prank(taker);
        uint256 positionId = c.fillOrder(order, signature, new uint256[](0));

        // M stores block.timestamp - duration for short positions; C stores block.timestamp + duration.
        uint256 expectedExpiration = block.timestamp + duration;
        assertTrue(c.positionExpirations(positionId) == expectedExpiration);
    }

    // Minimal ERC20-like receiver for the base asset interaction; records nothing needed for the assertion.
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function balanceOf(address) external pure returns (uint256) { return type(uint256).max; }
    function allowance(address, address) external pure returns (uint256) { return type(uint256).max; }
}
